fn largest_divisor(n: i8) -> i8 {
    assert!(n > 1);

    // If n has a divisor i (2 <= i <= sqrt(n)), then the largest proper divisor is n / i
    // where i is the smallest such divisor. If no such i exists, n is prime and the
    // largest proper divisor is 1.
    let nn = n as i16;

    let mut i: i16 = 2;
    while i * i <= nn {
        if nn % i == 0 {
            return (nn / i) as i8;
        }
        i += 1;
    }

    1
}